  async function saveConstructor(){captureDrafts();const binding=S.binding,button=root.querySelector('[data-team-save]');if(!snapshotCurrent(binding)){button.disabled=false;error('Проект изменился. Дождитесь состава нового проекта.');return}const changes=[];for(const node of root.querySelectorAll('[data-team-pane]')){const draft=draftFor(node.dataset.teamPane);if(draftHas(draft,'model')||draftHas(draft,'mode'))changes.push({node,draft})}if(!changes.length){LIVE.toast('Изменений модели и прав нет.');return}button.disabled=true;try{for(const change of changes){if(!snapshotCurrent(binding))throw Error('Проект изменился. Дождитесь состава нового проекта.');const id=change.node.dataset.teamPane,pane=S.data&&S.data.panes.find(row=>row.id===id),receipt=S.settings.get(id);if(!pane||!receipt)throw Error('Не удалось подтвердить настройки места. Обновите экран.');const selectedModel=draftHas(change.draft,'model')?change.draft.model:encodeURIComponent(pane.vendor)+'/'+encodeURIComponent(pane.model),[vendor,model]=selectedModel.split('/').map(decodeURIComponent),selectedMode=draftHas(change.draft,'mode')?change.draft.mode:pane.mode,rightsChanged=draftHas(change.draft,'mode');if(rightsChanged&&pane.busy)throw Error('Место сейчас отвечает — права можно изменить после завершения хода.');const body={vendor,model,mode:selectedMode,binding:{...receipt}},value=await LIVE.api('/api/panes/'+encodeURIComponent(id),body);if(!snapshotCurrent(binding))return;if(!value||value.ok!==true||!value.pane||value.pane.id!==id||value.pane.vendor!==vendor||value.pane.model!==model||value.pane.mode!==selectedMode)throw Error(value&&value.error||'Движок не подтвердил настройки места.');S.drafts.delete(draftKey(binding.project,id))}await LIVE.refreshStatus(true);if(!projectCurrent(binding))return;await sync(true);LIVE.toast('Модель и права сохранены. Со следующего хода.')}catch(failure){if(projectCurrent(binding))error(failure.message||'Настройки не сохранены.')}finally{button.disabled=false}}
  async function assignRole(role){const binding=S.binding;if(!snapshotCurrent(binding)){error('Проект изменился. Дождитесь состава нового проекта.');return}const catalog=Array.isArray(H.roleCatalog)&&H.roleCatalog.find(row=>row.role===role);if(!catalog||!catalog.available){error(catalog&&catalog.reason||'Роль сейчас недоступна.');return}const chat=(H.active||{}).room;if(!chat){error('Сначала начните разговор без роли — его можно назначить оркестратором.');return}try{const opened=await LIVE.api('/api/chats/'+encodeURIComponent(chat));if(!snapshotCurrent(binding))return;if(!validChat(opened,'room',chat))throw Error(opened&&opened.error||'Разговор без роли изменился.');const value=await LIVE.api('/api/assign',{role,chat,project:binding.project,revision:opened.chat.revision,documents:opened.chat.documents});if(!snapshotCurrent(binding))return;if(!value||value.ok!==true)throw Error(value&&value.error||'Роль не назначена.');await LIVE.refreshStatus(true);if(!projectCurrent(binding))return;await sync(true);LIVE.toast('Оркестратор назначен.')}catch(failure){if(projectCurrent(binding))error(failure.message||'Роль не назначена.')}}
  async function sendOrchestrator(){const row=S.derived&&S.derived.orch,input=root.querySelector('[data-team-chat-input]'),binding=S.binding;if(!row||!input)return;if(!snapshotCurrent(binding)){error('Проект изменился. Дождитесь состава нового проекта.');return}const message=input.value.trim();if(!message)return;const chat=row.chat;input.disabled=true;try{const value=await LIVE.api('/api/chat',{pane:row.id,message});if(!snapshotCurrent(binding)||S.derived&&S.derived.orch&&S.derived.orch.chat!==chat)return;if(!value||value.ok!==true)throw Error(value&&value.error||'Сообщение не отправлено.');input.value='';await sync(true)}catch(failure){if(projectCurrent(binding))error(failure.message||'Сообщение не отправлено.')}finally{input.disabled=false}}
  function openOrchestrator(){const row=S.derived&&S.derived.orch;if(!row||!snapshotCurrent()){error('Проект изменился. Дождитесь состава нового проекта.');return}LIVE.S.ui.pane=row.id;LIVE.save();location.href='01-chat.html'}
  function invalidateSnapshot(){if(!S.binding||projectCurrent(S.binding))return false;S.settings=new Map();S.error='Проект изменился. Дождитесь состава нового проекта.';draw();return true}
  async function sync(force=false){clearTimeout(retryTimer);if(!alive)return;if(!H.on||H.snapshotOnly){S.binding=null;S.settings=new Map();S.data=null;S.chats=new Map();S.derived=null;S.error='Движок недоступен — живые данные команды не показаны.';draw();return}if(S.loading){S.queued=true;return}const binding=projectBinding(),request=++S.request;S.loading=true;try{const data=await LIVE.api('/api/swarm');if(request!==S.request||!projectCurrent(binding))return;if(!validSnapshot(data,binding.project))throw Error('Снимок команды не прошёл проверку.');const pairs=await Promise.all(data.panes.map(async pane=>{if(!pane.chat)return [pane.id,null];try{const chat=await LIVE.api('/api/chats/'+encodeURIComponent(pane.chat));return [pane.id,validChat(chat,pane.id,pane.chat)?chat:null]}catch(failure){return [pane.id,null]}}));if(request!==S.request||!projectCurrent(binding))return;const settings=new Map(data.panes.map(pane=>[pane.id,settingReceipt(pane.id,binding)]));S.skipDraftCapture=mode==='constructor'&&!sameBinding(S.binding,binding);S.binding=binding;S.settings=settings;S.data=data;S.chats=new Map(pairs);S.derived=derive(data);S.error=null;draw();if(window.HARNESS_BOOT)window.HARNESS_BOOT.ready()}catch(failure){if(request===S.request&&projectCurrent(binding)){S.error=failure.message||'Не удалось прочитать команду.';draw()}}finally{if(request===S.request){S.loading=false;if(S.queued){S.queued=false;void sync(true)}else if(S.error&&alive)retryTimer=setTimeout(()=>{void sync(true)},3000)}}}
  let disclosureScope=null;
  function disclosureKey(button){const pane=button.closest('[data-key]'),role=button.closest('[data-team-role-key]');return pane?JSON.stringify(['pane',pane.dataset.key,button.dataset.tcReveal]):role?JSON.stringify(['catalog',role.dataset.teamRoleKey,button.dataset.tcReveal]):null}
  function draw(){
    const scope=S.binding&&JSON.stringify([S.binding,S.data?.instance]),saved=new Map();
    if(scope===disclosureScope&&snapshotCurrent())root.querySelectorAll('[data-tc-reveal]').forEach(button=>{const key=disclosureKey(button);if(key)saved.set(key,{text:button.textContent,open:button.getAttribute('aria-expanded')==='true',focus:document.activeElement===button})});
    if(mode==='work')drawWork();else if(mode==='constructor')drawConstructor();else if(mode==='queue')drawQueue();
    let focused=false;root.querySelectorAll('[data-tc-reveal]').forEach(button=>{const prior=saved.get(disclosureKey(button));if(!prior)return;if(prior.open&&prior.text===button.textContent){button.setAttribute('aria-expanded','true');button.nextElementSibling.hidden=false}if(prior.focus){button.focus({preventScroll:true});focused=true}});
    if(!focused&&[...saved.values()].some(item=>item.focus))(root.querySelector('[data-team-refresh]')||root.querySelector('[data-team-save]'))?.focus({preventScroll:true});
    disclosureScope=scope;
  }
  root.addEventListener('click',event=>{const plus=event.target.closest('[data-team-plus]');if(plus){openRoleMenu();return}const role=event.target.closest('[data-team-role]');if(role&&!role.disabled){void assignRole(role.dataset.teamRole);return}if(event.target.closest('[data-team-constructor]')){location.href='41-team-constructor.html';return}if(event.target.closest('[data-team-queue]')){location.href='41-team-queue.html';return}if(event.target.closest('[data-team-work]')){location.href='04-swarm.html';return}if(event.target.closest('[data-team-refresh]')){void (async()=>{if(!H.on)await LIVE.connect();await sync(true)})();return}if(event.target.closest('[data-team-send]')){void sendOrchestrator();return}if(event.target.closest('[data-team-open-chat]')){openOrchestrator();return}if(event.target.closest('[data-team-save]')){void saveConstructor();return}const instruction=event.target.closest('[data-team-instruction-open]');if(instruction){S.selected=instruction.dataset.teamInstructionOpen;void readInstruction(S.selected);return}const filter=event.target.closest('[data-team-filter]');if(filter){S.filter=filter.dataset.teamFilter;drawQueue()}});
  root.addEventListener('click',event=>{if(event.target.closest('[data-team-instruction-save]'))void saveInstruction();if(event.target.closest('[data-team-instruction-reload]'))void readInstruction(S.selected);if(event.target.closest('[data-team-own-open]')){CUI.view='role';persistConstructor();drawOwnRole(true);drawInstruction();root.querySelector('[data-team-own-editor]')?.scrollIntoView?.({block:'nearest'})}if(event.target.closest('[data-team-own-close]')){CUI.view='instruction';persistConstructor();drawOwnRole();drawInstruction()}});
  root.addEventListener('input',event=>{if(event.target.matches('[data-team-instruction-text]')){const draft=instructionDraft();if(draft){draft.text=event.target.value;draft.error='';persistConstructor();instructionStatus()}}const field=event.target.dataset.teamOwnField;if(field){const draft=ownDraft();if(draft&&!draft.pending){draft[field]=event.target.value;draft.opId=null;draft.created=null;draft.error='';persistConstructor()}}});
  root.addEventListener('change',event=>{if(event.target.matches('[data-team-instruction-shared]')){const draft=instructionDraft();if(draft)draft.sharedAccepted=event.target.checked}const field=event.target.dataset.teamOwnField;if(field){const draft=ownDraft();if(draft&&!draft.pending){draft[field]=event.target.value;draft.opId=null;draft.created=null;draft.error='';persistConstructor();if(field==='model')drawOwnRole(true)}}});
  root.addEventListener('submit',event=>{if(event.target.matches('[data-team-own-form]')){event.preventDefault();void createOwnRole()}});
  root.addEventListener('change',event=>{if(event.target.closest('[data-team-model],[data-team-mode]'))captureDrafts()});
  root.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&event.target.matches('[data-team-chat-input]')){event.preventDefault();void sendOrchestrator()}});
  document.addEventListener('click',event=>{if(event.target.closest('[data-team-role-menu]')){const role=event.target.closest('[data-team-role]');if(role&&!role.disabled){void assignRole(role.dataset.teamRole);closeRoleMenu()}else if(event.target.closest('[data-team-constructor]')){closeRoleMenu();location.href='41-team-constructor.html'}else placeRoleMenu();return}if(!event.target.closest('[data-team-plus-wrap]'))closeRoleMenu()});
  addEventListener('keydown',event=>{if(event.key==='Escape'&&floatingRoleMenu)closeRoleMenu(true)});
  addEventListener('resize',placeRoleMenu);

  function subscribe(){if(!S.events&&typeof LIVE.subscribeLiveEvents==='function')S.events=LIVE.subscribeLiveEvents(event=>{let value;try{value=JSON.parse(event.data)}catch(failure){return}if(!value.project||value.project===H.project)void sync()})}
  addEventListener('live:status',()=>{invalidateSnapshot();void sync(true)});
  addEventListener('pagehide',()=>{closeRoleMenu();alive=false;clearTimeout(retryTimer);S.request++;S.loading=false;S.queued=false;if(S.events){S.events.close();S.events=null}});
  addEventListener('pageshow',event=>{if(event.persisted){alive=true;void sync(true);subscribe()}});
  window.TEAM_LIVE={validSnapshot,validChat,derive,refresh:sync,state:S};
  {void (async()=>{if(!H.on)try{await LIVE.refreshStatus(true)}catch(failure){}await sync(true);subscribe()})()}
